effect.shader:
/** 0 na borda, 1 depois de `width`. Largura 0 devolve 1: o lado fica intacto. */
float sideMask(float distanceToEdge, float width) {
    if (width <= 0.0) return 1.0;
    return smoothstep(0.0, width, distanceToEdge);
}

void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    float mask =
        sideMask(acScreenNorm.x, fadeLeft) *
        sideMask(1.0 - acScreenNorm.x, fadeRight) *
        sideMask(acScreenNorm.y, fadeTop) *
        sideMask(1.0 - acScreenNorm.y, fadeBottom);

    fragColor = vec4(color.rgb, color.a * pow(mask, max(curveF, 0.01)));
}
